int count_overheated(int t[], int n, int limit) {
    int count = 0;
    for (int i = 0; i < n; i++) {
        if (t[i] > limit) {
            count++;
        }
    }
    return count;
}

int count_overheated(int t[], int n, int limit) {
    int count = 0;
    int i = 0;
    while (i < n) {
        if (t[i] > limit) {
            count++;
        }
        i++;
    }
    return count;
}

int count_overheated(int t[], int n, int limit) {
    int count = 0;
    int i;
    for (i = n - 1; i >= 0; i--) {
        if (t[i] > limit) {
            count = count + 1;
        }
    }
    return count;
}

